import json
from pathlib import Path
packet = 'e96a98a22124ba63287c3047da95b0adcc073077d23e52a4d0e368830afbc0b4'
patch = '1017529e2e4b4268992686b690268b13d3c4d3ca5d7e98195a853833314360d8'
for folder in ('products/distribution/sqlite-community-directory', 'products/reviews'):
    for path in sorted(Path(folder).rglob('*')):
        if path.suffix not in ('.json', '.md', '.txt') or path.stat().st_size > 150000:
            continue
        if folder.endswith('/reviews') and 'sqlite' not in str(path).lower():
            continue
        text = path.read_text(encoding='utf-8', errors='replace')
        if packet in text and patch in text:
            relevant = [line.strip()[:300] for line in text.splitlines() if any(word in line.lower() for word in ('verdict', 'reviewer', 'ready', 'decline', 'decision', 'submitted'))]
            print(json.dumps({'path': str(path), 'candidate_decision_lines': relevant[:12]}, ensure_ascii=False))
